/**
 * Sovereign AI Workbench — Multi-Agent Artifact Manager
 * 
 * Manages isolated code artifacts generated by specialist agents with strict provenance:
 * - Stores artifactId, workflowId, subtaskId, agentId, agentName, source, mimeType, filename, sha256, createdAt
 * - Validates artifact integrity and enforces strict workflow-level isolation.
 */

import crypto from 'node:crypto';
import path from 'node:path';
import { WorkflowResultValidator } from './workflow-result-validator.js';

export class ArtifactManager {
  constructor() {
    this.artifacts = new Map();
  }

  /**
   * Register a generated code/document artifact with cryptographic provenance.
   */
  registerArtifact({ workflowId, subtaskId, agentId, displayNumber, agentName, filename, content, language, mimeType, source }) {
    const cleanContent = typeof content === 'string' ? content : JSON.stringify(content, null, 2);
    const hash = crypto.createHash('sha256').update(cleanContent).digest('hex').slice(0, 16);
    const id = `art-${workflowId}-${subtaskId}-${filename}`;

    const ext = path.extname(filename).toLowerCase().replace('.', '');
    const detectedLanguage = language || ext || 'text';
    const lines = cleanContent.split('\n').length;
    const sizeBytes = Buffer.byteLength(cleanContent, 'utf8');

    // Run technology validation
    const validation = WorkflowResultValidator.validateArtifact({
      filename,
      content: cleanContent,
      language: detectedLanguage,
      subtaskId
    }, detectedLanguage);

    const artifact = {
      id,
      artifactId: id,
      workflowId,
      subtaskId,
      agentId,
      displayNumber: displayNumber || (agentId ? agentId.replace('agent-', '') : '061'),
      agentName,
      filename,
      language: detectedLanguage,
      mimeType: mimeType || this._detectMimeType(filename),
      content: cleanContent,
      sizeBytes,
      lines,
      sha256: hash,
      source: source || 'specialist-inference',
      isValid: validation.valid,
      validationError: validation.error || null,
      createdAt: new Date().toISOString()
    };

    this.artifacts.set(id, artifact);
    return artifact;
  }

  _detectMimeType(filename) {
    const ext = path.extname(filename).toLowerCase();
    const map = {
      '.html': 'text/html',
      '.css': 'text/css',
      '.js': 'application/javascript',
      '.ts': 'application/typescript',
      '.cpp': 'text/x-c++src',
      '.c': 'text/x-csrc',
      '.java': 'text/x-java-source',
      '.py': 'text/x-python',
      '.rs': 'text/x-rustsrc',
      '.go': 'text/x-go',
      '.json': 'application/json',
      '.sql': 'application/sql',
      '.md': 'text/markdown',
      '.txt': 'text/plain'
    };
    return map[ext] || 'application/octet-stream';
  }

  getArtifact(id) {
    return this.artifacts.get(id) || null;
  }

  getWorkflowArtifacts(workflowId) {
    return Array.from(this.artifacts.values()).filter(a => a.workflowId === workflowId);
  }

  clearWorkflowArtifacts(workflowId) {
    for (const [id, art] of this.artifacts.entries()) {
      if (art.workflowId === workflowId) {
        this.artifacts.delete(id);
      }
    }
  }

  clearAll() {
    this.artifacts.clear();
  }
}

export const globalArtifactManager = new ArtifactManager();
